import React from 'react';
import Container from "react-bootstrap/Container";
import Col from 'react-bootstrap/esm/Col';
import Image from 'react-bootstrap/esm/Image';
import Card from 'react-bootstrap/esm/Col';
import Button from 'react-bootstrap/Button';
import Row from 'react-bootstrap/esm/Row';


const DishPage = () => {
  const dish = {id: 1,	name: "Козацький драйв", price:	249, img:"aa1e0fdb-e208-43c6-9266-67621ddaac6f.jpg", typeId:2}
  const description = [
    {id:1, title: 'Козацький драйв', description: 'Рис, норі, лосось'},
    {id:2, title: 'Сякі-макі', description: 'Рис, норі, ікра щуки'},
    {id:3, title: 'Coca-cola 0.33', description: ''}
  ]
  return (
    <Container className='mt-3'>
      <Row>
      <Col md={4}>
        <Image width={300} height={300} src={dish.img}/>
        <Card>
          <h3>{dish.price} грн</h3>
          <Button variant='outline-dark'>
            Додати до корзини
          </Button>
        </Card>
      </Col>

      <Col md={4}>
        <h3>{dish.name}</h3>
        {description.map(info =>
          <Row key={info.id}>
            {info.title}: {info.description}
          </Row>
        )}
      </Col>
      </Row>
    </Container>
  );
};

export default DishPage;
